r=PROJECT_ROOT;run=r/'runs/20261107_v4_Visium_author_validation_v2';a=ad.read_h5ad(run/'reference/reference_and_heldout_PRIVATE.h5ad');meta=pd.read_csv(run/'reference/selected_cell_rows_PRIVATE.tsv.gz',sep='\t',index_col=0);assert a.obs_names.equals(meta.index) and a.obs_names.is_unique;ann=pd.read_pickle(r/'runs/20261106_v7_publication_marker_annotation_v1/stage_h_selective_subtype_restore_v4/annotation_frozen_V7_selective_subtype_20261106_v4_PRIVATE.pkl.gz');assert a.obs.node.astype(str).equals(ann.loc[a.obs_names,'final_annotation'].astype(str).rename('node'));assert a.obs.node.nunique()==50
